*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#070914;color:#f4f3f2;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:radial-gradient(ellipse at 50% 40%,#20243b,#080a14 74%);isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(6,7,17,.57),transparent 25%,transparent 65%,rgba(5,6,13,.83)),radial-gradient(ellipse at center,transparent 38%,rgba(2,3,10,.5) 100%);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 4.2vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(5,7,15,.53),transparent)}.brand{font-size:14px;letter-spacing:.18em;font-weight:800;text-decoration:none;color:#f7f5f1}.brand-mark{color:#ffb36e;font-size:20px;vertical-align:-2px;margin-right:8px}.brand-divider{color:#ffb36e;margin:0 9px}.brand-sub{font-size:10px;color:#a6a6b0;letter-spacing:.2em;font-weight:500}.mission{font-size:10px;letter-spacing:.16em;font-weight:700;color:#dddde4;display:flex;align-items:center;gap:12px}.mission-sep{color:#f18a5c}.mission #objective{color:#b4aab0;font-weight:500}.live-dot{width:7px;height:7px;border-radius:50%;background:#ff926e;box-shadow:0 0 12px #ff5b50}.icon-button{border:0;background:transparent;color:#dedde5;font-size:18px;cursor:pointer;letter-spacing:.08em}.icon-button span{font-size:9px;vertical-align:3px;margin-left:5px;letter-spacing:.13em}.boss-hud{position:absolute;z-index:3;top:11.2%;left:50%;transform:translateX(-50%);width:min(490px,43vw);text-align:center;transition:opacity .4s}.boss-title{display:flex;flex-direction:column;gap:4px}.boss-kicker{font-size:9px;letter-spacing:.3em;color:#e3a58e}.boss-title strong{font-family:'Barlow Condensed',sans-serif;font-size:25px;line-height:1;letter-spacing:.12em;font-weight:700}.boss-title i{color:#d39b8d;font-size:17px;font-style:normal;font-weight:500}.boss-health{height:8px;margin-top:12px;border:1px solid rgba(229,190,172,.48);background:rgba(9,8,17,.8);padding:1px;position:relative;clip-path:polygon(0 0,99.2% 0,100% 50%,99.2% 100%,0 100%,.8% 50%)}#boss-health-fill{width:100%;height:100%;background:linear-gradient(90deg,#d86c69,#ffb078);box-shadow:0 0 14px #f17d6b;transition:width .3s} .boss-phase-line{position:absolute;left:50%;top:-1px;height:8px;border-left:1px solid #fff9}.boss-meta{display:flex;justify-content:space-between;font-size:8px;color:#b7a9ac;letter-spacing:.13em;margin-top:6px}.chapter-card{position:absolute;z-index:5;left:8.2vw;top:50%;transform:translateY(-43%);width:360px;max-width:39vw;transition:opacity .8s,transform .8s;pointer-events:auto;text-shadow:0 2px 20px #000}.chapter-card.dismissed{opacity:0;transform:translate(-12px,-43%);pointer-events:none}.chapter-overline{display:flex;justify-content:space-between;color:#f0a582;font-size:9px;letter-spacing:.24em;font-weight:700}.chapter-card h1{font-family:'Barlow Condensed',sans-serif;font-size:clamp(68px,8.5vw,118px);line-height:.75;letter-spacing:-.04em;margin:19px 0 21px;font-weight:800}.chapter-card h1 em{font-style:normal;color:#e89170}.chapter-rule{width:54px;height:2px;background:#f1a17d;margin:0 0 14px}.chapter-card p{color:#d0cdd0;font-size:13px;line-height:1.55;max-width:285px;margin:0 0 23px}.start-button{background:#e8906f;color:#1c1215;border:0;padding:14px 19px;font-size:10px;letter-spacing:.18em;font-weight:800;cursor:pointer;clip-path:polygon(0 0,95% 0,100% 50%,95% 100%,0 100%);transition:background .2s,transform .2s}.start-button:hover{background:#ffc094;transform:translateY(-2px)}.start-button span{font-size:15px;margin-left:25px}.chapter-foot{position:absolute;top:calc(100% + 33px);left:0;right:-5vw;display:flex;justify-content:space-between;color:#a09ba3;font-size:8px;letter-spacing:.14em}.combat-hud{position:absolute;z-index:3;bottom:0;left:0;right:0;min-height:145px;padding:22px 4.2vw 23px;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(0deg,rgba(5,6,13,.95),rgba(7,8,17,.78) 69%,transparent);transition:opacity .35s}.player-readout{display:flex;gap:13px;align-items:center;width:260px}.portrait{width:49px;height:49px;border:1px solid rgba(248,168,133,.7);background:linear-gradient(135deg,#402c3a,#161522);display:flex;align-items:center;justify-content:center;flex-direction:column;position:relative;clip-path:polygon(0 0,100% 0,100% 80%,80% 100%,0 100%)}.portrait span{font-size:21px;color:#ffb18b;line-height:22px}.portrait b{font-family:'Barlow Condensed',sans-serif;letter-spacing:.17em;font-size:9px}.vitals{flex:1}.vital-label{display:flex;justify-content:space-between;color:#e2dce0;font-size:8px;letter-spacing:.16em;font-weight:700;margin-bottom:5px}.vital-track{height:5px;background:#332b35;margin-bottom:10px}.vital-track>div{height:100%;width:100%;background:linear-gradient(90deg,#df6f6b,#ffae85);box-shadow:0 0 8px #db7569;transition:width .2s}.rage-label{color:#e5ad87}.rage-label small{font-size:7px;color:#a89ca1}.rage-track{height:4px;background:#292333}.rage-track>div{width:0;height:100%;background:#ffd082;box-shadow:0 0 10px #f3b86e;transition:width .25s}.ability-row{display:flex;gap:9px;align-items:center}.ability{width:72px;height:57px;position:relative;border:1px solid rgba(211,201,211,.18);background:rgba(18,18,30,.7);display:flex;flex-direction:column;justify-content:center;padding-left:9px;color:#ddd5dc}.ability kbd{position:absolute;right:6px;top:5px;border:1px solid #756b77;color:#d4cbd2;padding:1px 4px;font-size:8px;font-family:inherit}.ability span{font-size:7px;letter-spacing:.15em;margin-top:14px}.ability i{position:absolute;left:8px;top:4px;font-size:15px;color:#f1a184;font-style:normal}.ability.ultimate{border-color:rgba(255,202,126,.38)}.ability.ultimate i{color:#ffd27f}.combo-readout{min-width:110px;text-align:right;display:flex;flex-direction:column;align-items:flex-end}.combo-readout b{font-family:'Barlow Condensed',sans-serif;font-size:46px;line-height:.9;color:#f5a37d}.combo-readout span{font-size:8px;letter-spacing:.2em}.combo-readout small{font-size:7px;color:#aa9da5;letter-spacing:.1em;margin-top:5px}.corner-note{z-index:3;position:absolute;bottom:158px;right:4.2vw;color:#b0aab3;font-size:8px;letter-spacing:.12em;display:flex;gap:9px;align-items:center}.corner-note kbd{border:1px solid #8b818b;padding:3px 6px;font-size:8px;font-family:inherit}.intro-flash{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:rgba(3,4,12,.3);font-family:'Barlow Condensed',sans-serif;font-size:clamp(20px,3vw,40px);font-weight:700;letter-spacing:.3em;text-shadow:0 0 25px #f2996d;animation:flashIn .7s ease both;pointer-events:none}.hidden{display:none!important}@keyframes flashIn{0%{opacity:0;letter-spacing:.6em;filter:blur(8px)}25%{opacity:1}100%{opacity:0;letter-spacing:.3em;filter:blur(0)}}.toast{position:absolute;z-index:4;top:31%;left:50%;transform:translate(-50%,-10px);font-family:'Barlow Condensed',sans-serif;font-size:clamp(16px,2vw,27px);font-weight:700;letter-spacing:.18em;color:#ffc49c;text-shadow:0 3px 18px #f66;opacity:0;transition:.35s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.qte{position:absolute;z-index:4;top:64%;left:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:14px;padding:10px 19px 10px 10px;background:rgba(11,10,20,.82);border:1px solid rgba(255,202,139,.55);box-shadow:0 0 35px #ff784444;animation:qtePulse .8s ease-in-out infinite alternate}.qte-ring{width:53px;height:53px;border:2px solid #ffc184;border-radius:50%;display:grid;place-items:center;box-shadow:0 0 18px #ffb07877}.qte-ring span{font-family:'Barlow Condensed';font-weight:800;font-size:27px}.qte b,.qte small{display:block;letter-spacing:.14em}.qte b{font-size:11px}.qte small{font-size:8px;color:#c5b7ba;margin-top:4px}@keyframes qtePulse{to{transform:translate(-50%,-50%) scale(1.05);box-shadow:0 0 45px #ff784466}}.ultimate-banner{position:absolute;z-index:4;top:38%;left:50%;transform:translate(-50%,-50%);font-family:'Barlow Condensed';font-size:clamp(30px,5.5vw,75px);font-weight:800;letter-spacing:.12em;color:white;text-shadow:0 0 8px white,0 0 35px #ff9a67,0 0 75px #ff6938;white-space:nowrap;animation:ultBanner 2.2s ease both;pointer-events:none}.ultimate-banner i{color:#ffc480;font-style:normal}@keyframes ultBanner{0%{opacity:0;transform:translate(-50%,-40%) scale(1.5);filter:blur(10px)}18%{opacity:1;transform:translate(-50%,-50%) scale(1)}78%{opacity:1}100%{opacity:0;transform:translate(-50%,-60%) scale(.9)}}.pause-overlay{position:absolute;inset:0;z-index:8;display:grid;place-items:center;background:rgba(4,5,12,.78);backdrop-filter:blur(8px)}.pause-card{text-align:center}.pause-card>span{font-size:9px;letter-spacing:.28em;color:#e6a17f}.pause-card h2{font:800 68px/.9 'Barlow Condensed';margin:14px 0 25px;letter-spacing:.12em}.pause-card button{background:#e8906f;color:#1c1215;border:0;padding:14px 22px;font-size:10px;font-weight:800;letter-spacing:.14em;cursor:pointer}.mobile-controls{display:none}.stick-zone{position:absolute;left:5vw;bottom:calc(3vh + env(safe-area-inset-bottom));width:132px;height:132px;touch-action:none}.stick-base{position:absolute;inset:0;border:1px solid #ffffff36;border-radius:50%;background:#0c0d19a8;display:grid;place-items:center;box-shadow:inset 0 0 30px #ffffff0a}.stick{width:53px;height:53px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#f3bb99,#a15c5e);border:1px solid #ffd1b177;box-shadow:0 3px 14px #0009;transform:translate(0,0)}.touch-actions{position:absolute;right:4vw;bottom:calc(3vh + env(safe-area-inset-bottom));width:185px;height:165px}.touch-btn{position:absolute;width:58px;height:58px;border-radius:50%;border:1px solid #ffbd945c;background:linear-gradient(140deg,#372633dc,#10121dea);box-shadow:0 0 18px #0008,inset 0 0 15px #ed9b7522;touch-action:none;display:flex;align-items:center;justify-content:center;flex-direction:column}.touch-btn span{font-size:20px;color:#ffc093}.touch-btn small{font-size:7px;letter-spacing:.1em;color:#eee}.strike-btn{right:4px;bottom:34px;width:72px;height:72px;background:linear-gradient(145deg,#8e4d4d,#401f34)}.strike-btn span{font-size:27px}.burst-btn{left:10px;bottom:38px}.dash-btn{left:41px;top:5px;width:50px;height:50px}.ult-btn{right:0;top:0;width:48px;height:48px;border-color:#ffd180}.ult-btn span{color:#ffdb8d}.pause-card{border:1px solid #ffffff2a;padding:38px 55px;background:#0e101d}
@media(max-width:700px){.topbar{height:55px;padding:0 17px}.brand{font-size:11px}.brand-mark{font-size:16px;margin-right:5px}.brand-sub{font-size:8px}.mission{display:none}.icon-button{font-size:15px}.icon-button span{font-size:8px}.boss-hud{top:72px;width:min(78vw,420px)}.boss-title strong{font-size:20px}.boss-title i{font-size:14px}.boss-kicker{font-size:8px}.boss-meta{font-size:7px}.chapter-card{left:7vw;top:36%;width:250px;max-width:65vw}.chapter-card h1{font-size:clamp(59px,16vw,91px);margin:14px 0 17px}.chapter-card p{font-size:11px;max-width:225px;margin-bottom:15px}.start-button{padding:12px 14px;font-size:9px}.chapter-foot{top:calc(100% + 20px);right:-30vw;font-size:6px}.combat-hud{bottom:auto;top:calc(100% - 112px);min-height:110px;padding:10px 15px 8px;align-items:flex-start}.player-readout{width:min(57vw,260px);gap:8px}.portrait{width:38px;height:41px}.portrait span{font-size:17px}.portrait b{font-size:8px}.vital-label{font-size:7px}.ability-row{display:none}.combo-readout{position:absolute;right:18px;top:9px;min-width:64px}.combo-readout b{font-size:33px}.combo-readout span,.combo-readout small{font-size:6px}.corner-note{display:none}.mobile-controls{display:block}.stick-zone{width:112px;height:112px;left:4vw;bottom:calc(16vh + env(safe-area-inset-bottom))}.stick{width:46px;height:46px}.touch-actions{transform:scale(.88);transform-origin:bottom right;bottom:calc(14.5vh + env(safe-area-inset-bottom));right:3vw}.toast{top:37%}.qte{top:56%}.vignette{background:linear-gradient(180deg,rgba(6,7,17,.5),transparent 23%,transparent 61%,rgba(5,6,13,.55)),radial-gradient(ellipse at center,transparent 38%,rgba(2,3,10,.45) 100%)}}
@media(max-height:570px) and (max-width:900px){.chapter-card{top:36%;transform:translateY(-30%) scale(.78);transform-origin:left center}.chapter-card.dismissed{transform:translate(-12px,-30%) scale(.78)}.boss-hud{top:59px}.combat-hud{top:auto;bottom:0;min-height:88px}.mobile-controls .stick-zone{bottom:100px}.touch-actions{bottom:94px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const canvas=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x080a17);
scene.fog=new THREE.FogExp2(0x0a0c1a,.012);
const camera=new THREE.PerspectiveCamera(42,1,.1,500);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.18;
const clock=new THREE.Clock();
scene.add(new THREE.HemisphereLight(0x9ca9e9,0x211c2c,1.65));
const keyLight=new THREE.DirectionalLight(0xffc7a6,3.8);keyLight.position.set(-12,23,14);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-35;keyLight.shadow.camera.right=35;keyLight.shadow.camera.top=30;keyLight.shadow.camera.bottom=-25;scene.add(keyLight);
const rimLight=new THREE.PointLight(0x648aff,80,65,2);rimLight.position.set(13,11,-14);scene.add(rimLight);
const fireLight=new THREE.PointLight(0xff774a,90,35,2);fireLight.position.set(-4,5,7);scene.add(fireLight);
const world=new THREE.Group();scene.add(world);
const mat=(color,rough=.75,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={ground:mat(0x252535,.95),stone:mat(0x494353,.88),dark:mat(0x171724,.7,.25),gold:mat(0xe4a56e,.42,.65),skin:mat(0xb86f68,.85),cloth:mat(0x272339,.8),light:mat(0xffbc8e,.3,.2),boss:mat(0x30273c,.38,.55),bossEdge:mat(0xe08873,.32,.6),black:mat(0x10111e,.8),planet:mat(0x75516c,.7)};
function mesh(geo,material,parent=world,pos=[0,0,0],scale){const o=new THREE.Mesh(geo,material);o.position.set(...pos);if(scale)o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function sphere(r,m,p,sc){return mesh(new THREE.SphereGeometry(r,20,16),m,world,p,sc)}
// A shattered temple suspended above the living world.
const floor=mesh(new THREE.CircleGeometry(38,96),mats.ground,world,[0,-.18,0]);floor.rotation.x=-Math.PI/2;
const disk=mesh(new THREE.CylinderGeometry(21,25,.75,72,1),mats.stone,world,[0,-.55,0]);
const ring=mesh(new THREE.TorusGeometry(21.3,.14,8,128),new THREE.MeshBasicMaterial({color:0xe9a17c}),world,[0,-.13,0]);ring.rotation.x=Math.PI/2;
for(let i=0;i<32;i++){const a=i/32*Math.PI*2;const r=22.8+(i%3)*1.8;const h=2+Math.random()*6;const rock=mesh(new THREE.BoxGeometry(1.2+Math.random()*2,h,1.4+Math.random()*2),i%4===0?mats.gold:mats.stone,world,[Math.cos(a)*r,h/2-.2,Math.sin(a)*r]);rock.rotation.y=a;rock.rotation.z=(Math.random()-.5)*.24}
for(let i=0;i<9;i++){const x=(i-4)*5.3+(Math.random()-.5)*1.8,z=-13-Math.random()*6;const h=6+Math.random()*12;const p=mesh(new THREE.CylinderGeometry(.6,1.35,h,6),i%3===0?mats.gold:mats.stone,world,[x,h/2-.15,z]);p.rotation.z=(Math.random()-.5)*.14;const cap=mesh(new THREE.CylinderGeometry(1.1,1.5,.7,6),mats.dark,world,[x,h-.1,z]);cap.rotation.y=.4}
// Cosmic backdrops and distant worlds.
const planet=sphere(13,mats.planet,[-25,12,-47],[1,1,.42]);planet.material=new THREE.MeshStandardMaterial({color:0x594563,roughness:.65,emissive:0x261a35,emissiveIntensity:.65});
const atmo=sphere(13.45,new THREE.MeshBasicMaterial({color:0xed927e,transparent:true,opacity:.09,side:THREE.BackSide}),[-25,12,-47],[1,1,.42]);
const moon=sphere(5,mat(0x334165,.65),[27,16,-53],[1,1,.55]);
const starGeo=new THREE.BufferGeometry(),starPos=[];for(let i=0;i<1000;i++){starPos.push((Math.random()-.5)*190,(Math.random()-.5)*115-3,-65-Math.random()*100)}starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPos,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xd9d8ff,size:.19,transparent:true,opacity:.8})));
const streaks=[];for(let i=0;i<20;i++){const s=mesh(new THREE.BoxGeometry(.035,.035,3+Math.random()*8),new THREE.MeshBasicMaterial({color:i%3===0?0xffa77e:0x809cff,transparent:true,opacity:.38}),world,[(Math.random()-.5)*90,8+Math.random()*40,-35-Math.random()*35]);s.rotation.z=(Math.random()-.5)*.4;streaks.push(s)}
// Hero: original, stylized guardian built from sculptural low-poly forms.
const hero=new THREE.Group();world.add(hero);hero.position.set(0,0,8);
const body=new THREE.Group();hero.add(body);
const torso=mesh(new THREE.CapsuleGeometry(.48,.82,5,10),mats.cloth,body,[0,1.42,0]);torso.rotation.x=-.06;
mesh(new THREE.SphereGeometry(.51,16,12),mats.skin,body,[0,2.1,0],[.82,.8,.74]);
const hair=mesh(new THREE.IcosahedronGeometry(.57,1),mat(0x242437,.55),body,[0,2.48,-.02],[1,.65,.95]);
for(let i=0;i<7;i++){const lock=mesh(new THREE.ConeGeometry(.15,.75,5),mat(0x26263a),body,[(i-3)*.14,2.36,-.18+Math.random()*.3]);lock.rotation.z=(i-3)*-.19;lock.rotation.x=-.28}
// Face mask / luminous eyes
mesh(new THREE.BoxGeometry(.52,.14,.12),mats.dark,body,[0,2.11,.48]);for(const x of [-.16,.16])mesh(new THREE.BoxGeometry(.105,.035,.035),new THREE.MeshBasicMaterial({color:0xffc086}),body,[x,2.13,.55]);
const shoulder=[];const arms=[];for(const side of [-1,1]){const sh=mesh(new THREE.IcosahedronGeometry(.37,1),mats.gold,body,[side*.63,1.85,0],[1,.85,1]);shoulder.push(sh);const arm=new THREE.Group();arm.position.set(side*.68,1.73,0);body.add(arm);mesh(new THREE.CapsuleGeometry(.18,.48,4,8),mats.skin,arm,[0,-.31,0]);mesh(new THREE.BoxGeometry(.35,.34,.42),mats.gold,arm,[0,-.66,.08]);mesh(new THREE.SphereGeometry(.22,12,10),mats.skin,arm,[0,-.87,.1]);arms.push(arm)}
const legs=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.25,.9,0);body.add(leg);mesh(new THREE.CapsuleGeometry(.22,.56,4,8),mats.dark,leg,[0,-.35,0]);mesh(new THREE.BoxGeometry(.35,.22,.52),mats.gold,leg,[0,-.72,.13]);legs.push(leg)}
for(let i=0;i<3;i++){const sash=mesh(new THREE.ConeGeometry(.25,1.5,4),i===0?mats.gold:mats.cloth,body,[(i-1)*.27,1.05,-.3]);sash.rotation.z=-.2+i*.2;sash.rotation.x=-.25}
const aura=new THREE.Group();hero.add(aura);const auraMat=new THREE.MeshBasicMaterial({color:0xffa16f,transparent:true,opacity:.18,side:THREE.DoubleSide,depthWrite:false});const auraRing=mesh(new THREE.TorusGeometry(1.05,.08,8,32),auraMat,aura,[0,1.1,0]);auraRing.rotation.x=Math.PI/2;const auraRing2=mesh(new THREE.TorusGeometry(1.45,.035,6,36),new THREE.MeshBasicMaterial({color:0xffcb8b,transparent:true,opacity:.4}),aura,[0,1.2,0]);auraRing2.rotation.x=Math.PI/2;
// The Hollow Sun: towering, multi-limbed god with a living eclipse for a heart.
const boss=new THREE.Group();world.add(boss);boss.position.set(0,0,-13);
const bossBody=new THREE.Group();boss.add(bossBody);mesh(new THREE.IcosahedronGeometry(2.65,2),mats.boss,bossBody,[0,5.1,0],[1,1.45,.8]);mesh(new THREE.SphereGeometry(1.12,24,18),new THREE.MeshStandardMaterial({color:0x160f22,emissive:0xff583e,emissiveIntensity:1.9,roughness:.3}),bossBody,[0,5.1,.78]);
